-- 00331 — 00385: إحصاء شهري دائم لبقع التوقف (للمقارنة «هذا الشهر مقابل السابق») — يبقى بعد خروج الشهر من النافذة المتدحرجة.
-- صف واحد صغير لكل شهر؛ يُحدَّث مع كل نسخ ليلي نهائي. القراءة لغرفة العمليات/IT/المدير العام فقط.
create table if not exists public.gps_hotspots_month_stats (
  month date primary key,
  spots int not null default 0,
  stops int not null default 0,
  total_minutes bigint not null default 0,
  multi_vehicle int not null default 0,
  by_class jsonb not null default '{}'::jsonb,
  by_recurrence jsonb not null default '{}'::jsonb,
  by_sector jsonb not null default '[]'::jsonb,
  updated_at timestamptz not null default now()
);
alter table public.gps_hotspots_month_stats enable row level security;
drop policy if exists "gps hotspots month stats read" on public.gps_hotspots_month_stats;
create policy "gps hotspots month stats read" on public.gps_hotspots_month_stats for select to authenticated using (app.has_role(array['ops_room','it_admin','super_admin']));
revoke insert, update, delete on public.gps_hotspots_month_stats from anon, authenticated;

create or replace function public.gps_hotspots_month_stats_refresh(p_month date) returns void
language plpgsql security definer set search_path = public, app as $$
declare m date := date_trunc('month', p_month)::date;
begin
  insert into public.gps_hotspots_month_stats (month, spots, stops, total_minutes, multi_vehicle, by_class, by_recurrence, by_sector, updated_at)
  select m, count(*), coalesce(sum(stops_count), 0), coalesce(sum(total_minutes), 0), count(*) filter (where vehicles_count > 1),
    jsonb_build_object('light', count(*) filter (where dominant_class = 'light'), 'medium', count(*) filter (where dominant_class = 'medium'), 'heavy', count(*) filter (where dominant_class = 'heavy')),
    jsonb_build_object('once', count(*) filter (where recurrence = 'once'), 'recurring', count(*) filter (where recurrence = 'recurring'), 'frequent', count(*) filter (where recurrence = 'frequent')),
    coalesce((select jsonb_agg(jsonb_build_object('sector_id', s.sid, 'sector_name', s.sname, 'spots', s.c) order by s.c desc)
              from (select u.sid, min(u.sname) sname, count(*) c from public.gps_hotspots h2, unnest(h2.sector_ids, h2.sector_names) u(sid, sname) where h2.month = m group by u.sid) s), '[]'::jsonb),
    now()
  from public.gps_hotspots h where h.month = m
  on conflict (month) do update set spots = excluded.spots, stops = excluded.stops, total_minutes = excluded.total_minutes, multi_vehicle = excluded.multi_vehicle,
    by_class = excluded.by_class, by_recurrence = excluded.by_recurrence, by_sector = excluded.by_sector, updated_at = now();
end $$;
revoke all on function public.gps_hotspots_month_stats_refresh(date) from public, anon, authenticated;

create or replace function public.gps_hotspots_replace_month(p_month date, p_rows jsonb, p_first boolean default true, p_final boolean default true, p_thresholds jsonb default '{}'::jsonb) returns jsonb
language plpgsql security definer set search_path = public, app as $$
declare m date := date_trunc('month', p_month)::date; n int := 0; total int;
begin
  if auth.role() <> 'service_role' then raise exception 'GPS_FORBIDDEN'; end if;
  if p_first then delete from public.gps_hotspots where month = m; end if;
  insert into public.gps_hotspots (month, wh_id, lat, lng, stops_count, days_count, vehicles_count, total_minutes, avg_minutes, max_minutes,
    light_count, medium_count, heavy_count, dominant_class, recurrence, first_at, last_at, sector_ids, sector_names, vehicles, days, hours, synced_at)
  select m, (r ->> 'id')::bigint, (r ->> 'lat')::double precision, (r ->> 'lng')::double precision,
    coalesce((r ->> 'stops_count')::int, 0), coalesce((r ->> 'days_count')::int, 0), coalesce((r ->> 'vehicles_count')::int, 0),
    coalesce((r ->> 'total_minutes')::int, 0), coalesce((r ->> 'avg_minutes')::int, 0), coalesce((r ->> 'max_minutes')::int, 0),
    coalesce((r ->> 'light_count')::int, 0), coalesce((r ->> 'medium_count')::int, 0), coalesce((r ->> 'heavy_count')::int, 0),
    coalesce(r ->> 'dominant_class', 'light'), coalesce(r ->> 'recurrence', 'once'),
    (r ->> 'first_at')::timestamptz, (r ->> 'last_at')::timestamptz,
    coalesce((select array_agg(x::int) from jsonb_array_elements_text(coalesce(r -> 'sector_ids', '[]'::jsonb)) x), '{}'),
    coalesce((select array_agg(x) from jsonb_array_elements_text(coalesce(r -> 'sector_names', '[]'::jsonb)) x), '{}'),
    coalesce(r -> 'vehicles', '[]'::jsonb),
    coalesce((select array_agg(x::date) from jsonb_array_elements_text(coalesce(r -> 'days', '[]'::jsonb)) x), '{}'),
    coalesce((select array_agg(x::int) from jsonb_array_elements_text(coalesce(r -> 'hours', '[]'::jsonb)) x), '{}'),
    now()
  from jsonb_array_elements(coalesce(p_rows, '[]'::jsonb)) r
  on conflict (month, wh_id) do update set lat = excluded.lat, lng = excluded.lng, stops_count = excluded.stops_count, days_count = excluded.days_count,
    vehicles_count = excluded.vehicles_count, total_minutes = excluded.total_minutes, avg_minutes = excluded.avg_minutes, max_minutes = excluded.max_minutes,
    light_count = excluded.light_count, medium_count = excluded.medium_count, heavy_count = excluded.heavy_count, dominant_class = excluded.dominant_class,
    recurrence = excluded.recurrence, first_at = excluded.first_at, last_at = excluded.last_at, sector_ids = excluded.sector_ids, sector_names = excluded.sector_names,
    vehicles = excluded.vehicles, days = excluded.days, hours = excluded.hours, synced_at = now();
  get diagnostics n = row_count;
  select count(*) into total from public.gps_hotspots where month = m;
  if p_final then
    insert into public.gps_hotspots_sync (month, rows_count, thresholds, synced_at) values (m, total, coalesce(p_thresholds, '{}'::jsonb), now())
    on conflict (month) do update set rows_count = excluded.rows_count, thresholds = excluded.thresholds, synced_at = now();
    perform public.gps_hotspots_month_stats_refresh(m);
  end if;
  return jsonb_build_object('month', to_char(m, 'YYYY-MM'), 'inserted', n, 'total', total, 'final', p_final);
end $$;

-- قائمة الإحصاءات الشهرية (الأحدث أولاً) للمقارنة في الواجهة
create or replace function public.gps_hotspots_month_stats() returns jsonb
language plpgsql stable security definer set search_path = public, app as $$
begin
  if auth.uid() is null or not app.has_role(array['ops_room','it_admin','super_admin']) then raise exception 'GPS_FORBIDDEN'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('month', to_char(s.month, 'YYYY-MM'), 'spots', s.spots, 'stops', s.stops, 'total_minutes', s.total_minutes, 'multi_vehicle', s.multi_vehicle,
    'by_class', s.by_class, 'by_recurrence', s.by_recurrence, 'by_sector', s.by_sector, 'updated_at', s.updated_at) order by s.month desc) from public.gps_hotspots_month_stats s), '[]'::jsonb);
end $$;
revoke all on function public.gps_hotspots_month_stats() from public, anon;
grant execute on function public.gps_hotspots_month_stats() to authenticated;

-- تعبئة الأشهر المنسوخة سابقاً
do $$ declare r record; begin for r in select distinct month from public.gps_hotspots loop perform public.gps_hotspots_month_stats_refresh(r.month); end loop; end $$;

